#!/bin/bash
# Nối ảnh mốc 7 gag còn lại phim #1156 tập 1 bằng VideoExpress (vx-noi-moc.mts) — chạy lần lượt (một phiên br). Ra: giay-cat/ra/<gag>-vx/ghep.mp4
# Gửi lại riêng đoạn hỏng: LAI=2,4 bash giay-cat/vx-7gag.sh gag6-bong · chạy thử (không gửi): VX_CHAY= bash giay-cat/vx-7gag.sh · chạy lại một gag: bash giay-cat/vx-7gag.sh gag3-ban-co   ·   chỉ lấy về (đã gửi): LAY=1 bash giay-cat/vx-7gag.sh gag3-ban-co
cd "$(dirname "$0")/.." || exit 1
R=giay-cat/ra; K=' Only the characters already in the picture move; everything else stays perfectly still.'   # câu cấm ("no other people, no vehicles") không giữ được — mô hình vẫn bịa (02/11/2026)
chay() { g=$1; giay=$2; nhip=$3; m=$(ls $R/$g-ve/ve-*.jpg | sort -V | paste -sd, -)
  echo "=== $g $(date +%H:%M)"
  VX_CHAY=${VX_CHAY-1} ../../node_modules/.bin/tsx scripts/vx-noi-moc.mts --moc=$m --giay=$giay --ra=$R/$g-vx --nhip="$nhip" ${LAY:+--lay} ${LAI:+--lai=$LAI} || echo "LOI $g"; }
gia() { case $1 in
  gag1-go-ray) echo "1.2,0.55,0.65,4.1|An old flower vendor with a bamboo carrying pole and two flower baskets walks in from the left edge and walks steadily to the right; a small boy sits on the rail stacking sticks, a tabby cat sleeps beside him.$K|Without stopping, the vendor dips the front end of her bamboo pole down twice, tapping; the boy and the cat look up startled.$K|The boy and the cat leap off the rail onto the doorstep behind; the vendor keeps walking right.$K|The vendor walks on to the right and out of frame; the boy and the cat stay on the doorstep, the boy grins, the cat sits calmly; the little stack of sticks stays standing on the rail.$K";;
  gag2-barie) echo "1.2,0.3,0.5,4.5|An old flower vendor with a carrying pole walks in from the left and walks steadily right; a Western backpacker couple taking a selfie step backwards from the doorstep onto the rail.$K|Without stopping, the vendor lowers the front end of her pole across behind the couple like a barrier gate; they bump into it.$K|The couple bounce back and press flat against the wall; the vendor lifts her pole and keeps walking.$K|The vendor walks on to the right and out of frame; the couple stay pressed against the wall, look at each other and burst out laughing.$K";;
  gag3-ban-co) echo "1.3,0.6,2.1,2.5|An old flower vendor with a carrying pole walks in from the left and walks steadily right; two men on stools play chess on a small folding table on the rail.$K|Without stopping, she flips the folding table up with the end of her pole; it folds flat and stands upright against the wall, the chessboard pinned upright.$K|The vendor walks on to the right and out of frame; the two men keep staring at the upright board.$K|The two men slowly tilt their heads sideways together to read the upright chessboard.$K";;
  gag6-bong) echo "1.2,1.2,0.45,2.65|An old flower vendor walks in from the left; as she passes she pokes the front end of her pole up at the shop awning; a boy below looks up pouting.$K|The vendor lowers her pole and walks on to the right; the boy keeps looking up, pouting.$K|The boy flinches as if something bounced on his head, then catches a yellow ball against his chest.$K|The vendor walks out of frame to the right; the boy blinks, then grins, hugging the ball.$K";;
  gag7-dep) echo "1.45,0.85,0.65,3.05|An old flower vendor walks in from the left; a schoolgirl on the balcony leans over pointing; two men sit on stools below; the vendor flicks the front end of her pole upward.$K|The vendor lowers her pole and walks on; the girl straightens up and laughs, holding her white sandal.$K|Two red paper lanterns drop down over the two seated men's heads; the vendor keeps walking right.$K|The vendor walks out of frame to the right; the two men sit still and dazed with lanterns over their heads; the girl laughs.$K";;
  gag8-meo) echo "1.3,0.35,0.85,4.0|An old flower vendor walks in from the left and walks steadily right; a grey tabby cat crouches frozen between the rails.$K|Without stopping, she scoops the cat up with the front basket and flicks her pole upward; the cat is gone from the rail.$K|The vendor walks on; a tabby cat appears sitting on the balcony railing above.$K|The vendor walks out of frame to the right; the cat sits smugly on the balcony railing licking its lips.$K";;
  gag9-cu) echo "1.35,0.55,2.1,2.5|Warm evening light. An old flower vendor walks in from the left; an old man dozes on a red stool at the edge of the rail.$K|Without stopping, she slides the end of her pole under the stool and tips the stool with the sleeping old man back onto the doorstep.$K|The vendor walks on to the right and out of frame; the old man keeps dozing on the doorstep.$K|The old man opens his eyes and slowly bows politely, hands together.$K";;
esac; }
for g in ${@:-gag1-go-ray gag2-barie gag3-ban-co gag6-bong gag7-dep gag8-meo gag9-cu}; do v=$(gia $g); chay $g "${v%%|*}" "${v#*|}"; done
echo "=== xong $(date +%H:%M)"
